contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // depositor: address that will call Deposit (must be this contract)
    // amt: amount of wei to send with Deposit
    function run(address depositor, uint256 amt) public payable {
        // require this contract holds enough balance to send amt
        require(address(this).balance >= amt);
        // ensure depositor is this contract (we will call Deposit via this contract)
        require(depositor == address(this));

        // read old balance via public getter
        uint256 oldBal = c.balances(depositor);

        // perform deposit on c, sending amt wei
        c.Deposit{value: amt}();

        // read new balance
        uint256 newBal = c.balances(depositor);

        // property: newBal == oldBal + amt
        assert(newBal == oldBal + amt);
    }

    // allow contract to receive ETH so it can call c.Deposit with value
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // drive: call Deposit with value 'v'. We require this contract have at least v wei.
    // We observe: call does not revert, balances[msg.sender] unchanged when v==0, and a Log entry is still produced (History length increases).
    // We cannot access Log directly, but we can observe c.balances and address(c).balance.

    // To observe log creation we use the fact that on P Deposit always calls Log.AddMessage even for zero-value deposits.
    // However Log contract is separate; since we may not access it, we instead check two distinguishing effects:
    // - On P, calling Deposit with v==0 does NOT revert and leaves balances[this] unchanged (still same) and address(c).balance unchanged.
    // - On M (mutant), Deposit requires msg.value>0, so calling with v==0 will revert.

    // Single external test function per rules.
    function runTest(uint v) public payable {
        require(address(this).balance >= v, "insufficient test balance");

        // read balance before
        uint balBefore = c.balances(address(this));
        uint contractBalBefore = address(c).balance;

        // If v==0, original contract allows call and does not change balances; mutant reverts.
        // We perform the state-changing call as its own top-level statement.
        c.Deposit{value: v}();

        // observe after
        uint balAfter = c.balances(address(this));
        uint contractBalAfter = address(c).balance;

        // Assert: if v==0 then call succeeded (we reached here) and balances unchanged and contract balance unchanged.
        // This property holds on original P for all inputs but is violated by mutant M because mutant would have reverted earlier for v==0.
        assert(!(v == 0) || (balAfter == balBefore && contractBalAfter == contractBalBefore));
    }

    // allow funding this test contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address sender, uint amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        // call Deposit forwarding `amount` wei
        try c.Deposit{value: amount}() { reverted = false; } catch { reverted = true; }
        // In the original contract, Deposit never reverts for any amount (including 0). The mutant rejects zero-value deposits and thus may revert when amount == 0.
        assert(reverted == false);
    }
    receive() external payable { }
}

