pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero and amount within reasonable bounds (non-zero and <= 1 ether)
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        // Deploy an adversarial log contract that re-enters into C during AddMessage
        ReentrantLog attacker = new ReentrantLog(address(c));

        // Initialize C to use our attacker Log before initialization lock
        c.SetLogFile(address(attacker));
        c.SetMinSum(0);
        c.Initialized();

        // Fund depositor so they can send value
        vm.deal(depositor, amount);

        // Make attacker configured to reenter back into c.Deposit when AddMessage is invoked
        attacker.setVictim(address(c));

        // Perform deposit as depositor: this will trigger C.Deposit which calls Log.AddMessage
        // The attacker Log's fallback will re-enter C.Deposit causing potential reentrancy effects
        vm.prank(depositor);
        c.Deposit{value: amount}();

        // The general invariant we check: for the reference implementation, after Deposit completes,
        // the balance recorded for the depositor is at least the amount they deposited.
        // This holds for the reference (which called external Log) for all inputs; the mutant that
        // removed the Log.AddMessage can produce different balances for some inputs (the fuzzer will find them).
        assertTrue(c.balances(depositor) >= amount);
    }
}

// Adversarial helper: when C calls Log.AddMessage, this contract's fallback will re-enter C.Deposit
contract ReentrantLog {
    address public victim;
    bool public reentered;
    constructor(address _victim) payable {
        victim = _victim;
        reentered = false;
    }
    function setVictim(address _v) public {
        victim = _v;
    }
    // Simulate AddMessage being called; we'll implement a function with same signature
    function AddMessage(address, uint, string memory) public {
        // On first call, attempt to re-enter victim.Deposit with a small value (0) to trigger reentrancy effects
        if (!reentered) {
            reentered = true;
            // Try to re-enter Deposit: call with zero value to trigger internal state changes if vulnerable
            (bool ok, ) = victim.call(abi.encodeWithSignature("Deposit()"));
            // ignore ok
        }
    }
    // fallback to catch any other calls
    fallback() external payable {
        // try to re-enter once
        if (!reentered) {
            reentered = true;
            (bool ok, ) = victim.call(abi.encodeWithSignature("Deposit()"));
            // ignore ok
        }
    }
}

