    C c;

    function setUp() public { c = new C(); }

    // General rule: For any depositor and deposit amount, when we point C.Log to
    // a reentrant attacker which on AddMessage will reenter and try to collect funds,
    // the reference C's Deposit which calls Log.AddMessage guarantees that
    // balances(depositor) >= deposited amount after Deposit returns.
    // The mutant that removes the Log.AddMessage may make balances differ for some inputs.
    function testFuzz_property(address depositor, uint256 amount) public {
