        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        // Deploy adversarial Log that reenters C when AddMessage is invoked.
        ReentrantLog attacker = new ReentrantLog(address(c));

        // Set Log in C before initialization
        c.SetLogFile(address(attacker));
        // set a MinSum low so collect path is available
