        c.Initialized();

        // Fund depositor
        vm.deal(depositor, amount);

        // The attacker will attempt reentrancy during AddMessage: when Deposit calls
        // Log.AddMessage, attacker.receiveAddMessage will call back into c.Collect
        // We want to observe balances(depositor) after Deposit completes.

