        c.Deposit{value: amount}();

        // The universal property we assert: after Deposit returns, balances(depositor) >= amount
        // (reference C with Log.AddMessage satisfies this for all inputs; mutant removing AddMessage
        // can break it because absence of external call changes reentrancy timing/behavior)
