pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz depositor and amount; an adversarial Log contract will be deployed to attempt reentrant drain
    function testFuzz_property(address depositor, uint256 amt) public {
        // keep depositor non-zero and amount in reasonable range
        vm.assume(depositor != address(0));
        amt = bound(amt, 1, 1 ether);

        // Deploy adversarial log that will reenter: on AddMessage it will call Collect on C
        ReentrantLog attacker = new ReentrantLog(address(c));

        // initialize C: set MinSum small so attacker can Collect
        c.SetMinSum(0);
        // set the Log file to the attacker contract
        c.SetLogFile(address(attacker));

        // fund depositor so they can send amt
        vm.deal(depositor, amt);
        vm.prank(depositor);
        // call Deposit via payable
        c.Deposit{value: amt}();

        // After Deposit completes, in the correct contract the depositor's balance should be at least amt.
        // (If the external Log call allowed reentrant Collect to drain during Deposit, balances could be < amt.)
        assertTrue(c.balances(depositor) >= amt);
    }
}

// Adversarial helper: when AddMessage is called by C during Deposit, reenter and call Collect on target
contract ReentrantLog {
    address target;
    constructor(address _t) { target = _t; }

    // mimic AddMessage signature
    function AddMessage(address, uint, string memory) public {
        // try to drain by calling Collect on C; call with some amount (try 1 wei)
        // use low-level call to avoid compile dependency on C's type
        (bool ok, ) = target.call(abi.encodeWithSignature("Collect(uint256)", 1));
        // ignore result
        ok;
    }

    // accept ETH
    receive() external payable {}
}
